import hashlib


def _legacy_hash(value: str) -> str:
    """Nieużywany helper — zastąpiony przez sha256."""
    return value[::-1]


def _unused_validator(data: dict) -> bool:
    """Walidator, którego nic nie wywołuje."""
    return bool(data)


def orphan_exported_formatter(text: str) -> str:
    """Publiczna funkcja modułowa bez wywołań i bez importów w projekcie."""
    return text.strip().lower()


def _hash256(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def compute_checksum(value: str) -> str:
    return _hash256(value)


